<script setup lang="ts">
import {onUnmounted,ref,watch} from 'vue';
import InfoHint from '../../shared/ui/InfoHint.vue';
import {NButton,NCard} from 'naive-ui';
import {api,ApiError} from '../../shared/api';
import type {Overview} from '../tasks/useAdminTasks';
const props=defineProps<{workspaceId:string}>(),emit=defineEmits<{sessionExpired:[]}>();
const facts=ref<Overview|null>(null),loading=ref(false),failed=ref(false);let controller:AbortController|undefined;
async function load(){if(loading.value)return;controller?.abort();const c=new AbortController();controller=c;loading.value=true;failed.value=false;try{const r=await api<Overview>(`/workspaces/${encodeURIComponent(props.workspaceId)}/task-management/overview`,c.signal);if(controller===c&&!c.signal.aborted)facts.value=r;}catch(e){if(controller===c&&!c.signal.aborted){failed.value=true;if(e instanceof ApiError&&[401,403].includes(e.status))facts.value=null;if(e instanceof ApiError&&e.status===401)emit('sessionExpired');}}finally{if(controller===c)loading.value=false;}}
defineExpose({refresh:load});
watch(()=>props.workspaceId,()=>{controller?.abort();loading.value=false;facts.value=null;void load();},{immediate:true});onUnmounted(()=>controller?.abort());
</script>
<template><section aria-label="工作区任务概况" class="task-overview"><p v-if="loading&&!facts" role="status">正在读取任务概况…</p><p v-else-if="failed" role="alert">任务概况暂时无法读取。<NButton text @click="load">重试概况</NButton></p><template v-if="facts"><div class="overview-grid"><NCard size="small"><span>数字员工</span><strong>{{facts.employees}}</strong></NCard><NCard size="small"><span>对话</span><strong>{{facts.conversations}}</strong></NCard><NCard size="small"><span>进行中</span><strong>{{facts.activeTasks}}</strong></NCard><NCard size="small"><span>已完成</span><strong>{{facts.succeeded}}</strong></NCard><NCard size="small"><span>失败</span><strong>{{facts.failed}}</strong></NCard><NCard size="small"><span class="stat-title">成功率<InfoHint label="任务统计范围">当前工作区；成功率按成功与失败任务计算，取消和未结束任务不计入分母。</InfoHint></span><strong>{{facts.successRate===null?'暂无样本':`${(facts.successRate*100).toFixed(1)}%`}}</strong></NCard></div><NButton class="overview-refresh" text size="small" @click="load">刷新概况</NButton></template></section></template>
<style scoped>.task-overview{margin-bottom:.75rem;position:relative}.overview-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:0;border:1px solid var(--subtle);border-radius:12px;overflow:hidden;background:var(--surface)}.overview-grid span{display:block;color:var(--muted);font-size:.875rem}.overview-grid strong{display:block;margin-top:.25rem;font-size:1.5rem;line-height:2rem;font-weight:600}.stat-title{display:flex!important;align-items:center;min-height:2rem}.overview-grid :deep(.n-card__content){padding:.75rem 1rem}.overview-refresh{display:flex;margin:.25rem 0 0 auto}@media(max-width:47.5rem){.overview-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:.75rem}}</style>

<style scoped>.overview-grid :deep(.n-card){border:0;border-radius:0;border-right:1px solid var(--subtle)}.overview-grid :deep(.n-card:last-child){border-right:0}.overview-grid :deep(.n-card__content){display:flex;flex-direction:column-reverse;justify-content:center;padding:16px 20px}.overview-grid strong{margin:0 0 4px;line-height:28px}.stat-title{min-height:0}.overview-refresh{font-size:12px}.overview-grid span{font-size:12px}@media(max-width:1000px){.overview-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:760px){.overview-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
